class SetupForm:Form {TextBox location=new TextBox();Label status=new Label();Button install=new Button();bool completed;CheckBox shortcut=new CheckBox(),launch=new CheckBox();public SetupForm(){Text="오름목 · 데스크톱 앱 설치";Font=new Font("맑은 고딕",10);BackColor=Color.FromArgb(247,246,240);Width=610;Height=420;StartPosition=FormStartPosition.CenterScreen;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;var panel=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(30),ColumnCount=1};Controls.Add(panel);panel.Controls.Add(new Label{Text="오름목  OREUM MOK",AutoSize=true,Font=new Font(Font.FontFamily,23,FontStyle.Bold),ForeColor=Color.FromArgb(28,58,45)});panel.Controls.Add(new Label{Text="Windows 전용 프로그램 설치 · 브라우저 / WebView 미사용\n기존 오름목을 종료한 뒤 설치하세요. 계정·고객 자료는 보존합니다.",AutoSize=true});panel.Controls.Add(new Label{Text="설치 폴더",AutoSize=true});location.Text=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","OreumMokNative");location.Dock=DockStyle.Top;panel.Controls.Add(location);shortcut.Text="바탕화면에 오름목 아이콘 만들기";shortcut.Checked=true;shortcut.AutoSize=true;panel.Controls.Add(shortcut);launch.Text="설치 후 프로그램 실행";launch.Checked=true;launch.AutoSize=true;panel.Controls.Add(launch);status.AutoSize=true;panel.Controls.Add(status);install.Text="설치 / 업그레이드";install.Height=42;install.Dock=DockStyle.Top;install.Click+=(s,e)=>{if(completed){Close();return;}install.Enabled=false;try{status.Text=NativeInstall.Run(location.Text,shortcut.Checked,launch.Checked);install.Text="닫기";install.Enabled=true;completed=true;}catch(Exception ex){status.Text=ex.Message;install.Enabled=true;}};panel.Controls.Add(install);}}
